          border-color: ButtonBorder;
        }

        .eyebrow,
        .required,
        .optional,
        .helper-text {
          color: CanvasText;
        }

        button,
        .skip-link {
          border: 0.125rem solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div id="support-form-root"></div>
    </main>

    <script>
      const formFields = [
        {
          id: "full-name",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Johnson"
        },
        {
          id: "email-address",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@example.com"
        },
        {
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          helperText: "Optional. Use international format when possible, for example +1 555 123 4567."
        }
      ];

      function FormField(field) {
        const wrapper = document.createElement("div");
        wrapper.className = "form-field";

        const label = document.createElement("label");
        label.htmlFor = field.id;
        label.textContent = field.label;

        if (field.required) {
          const marker = document.createElement("span");
          marker.className = "required";
          marker.setAttribute("aria-hidden", "true");
          marker.textContent = " *";
          label.append(marker);
        } else {
          const optional = document.createElement("span");
          optional.className = "optional";
          optional.textContent = " (optional)";
          label.append(optional);
        }

        const input = document.createElement("input");
        input.id = field.id;
        input.name = field.id;
        input.type = field.type;
        input.autocomplete = field.autocomplete;
        input.placeholder = field.placeholder;

        if (field.required) {
          input.required = true;
          input.setAttribute("aria-required", "true");
        }

        wrapper.append(label, input);

        if (field.helperText) {
          const helper = document.createElement("p");
          helper.id = `${field.id}-helper`;
          helper.className = "helper-text";
          helper.textContent = field.helperText;
          input.setAttribute("aria-describedby", helper.id);
          wrapper.append(helper);
        }

        return wrapper;
      }

      function SupportContactForm() {
        const section = document.createElement("section");
        section.className = "support-card";
        section.setAttribute("aria-labelledby", "support-title");

        const eyebrow = document.createElement("p");
        eyebrow.className = "eyebrow";
        eyebrow.textContent = "Support";

        const heading = document.createElement("h1");
        heading.id = "support-title";
        heading.textContent = "Contact our team";

        const intro = document.createElement("p");
        intro.className = "intro";
        intro.textContent =
          "Tell us how to reach you and a support specialist will follow up with the next steps.";

        const form = document.createElement("form");
        form.noValidate = false;
        form.append(...formFields.map(FormField));

        const button = document.createElement("button");
        button.type = "submit";
        button.textContent = "Submit support request";
        form.append(button);

        form.addEventListener("submit", (event) => {
          const firstInvalidField = form.querySelector(":invalid");

          if (firstInvalidField) {
            event.preventDefault();
            firstInvalidField.focus();
          }
        });

        section.append(eyebrow, heading, intro, form);
        return section;
      }

      document
        .querySelector("#support-form-root")
        .append(SupportContactForm());
    </script>
  </body>
</html>
