        padding: 0.75rem 1rem;
        color: var(--button-text);
        background: var(--accent-strong);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 0.1875rem solid var(--text);
        outline-offset: 0.1875rem;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .support-card {
        width: min(100%, 42rem);
        border: 0.0625rem solid var(--panel-border);
        border-radius: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2.5rem);
        background: color-mix(in srgb, var(--panel-bg) 94%, transparent);
        box-shadow: 0 1.5rem 4rem var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3.75rem);
        line-height: 1.05;
      }

      .intro {
        max-width: 36rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        color: var(--text);
        font-weight: 700;
      }

      .required {
        color: var(--accent);
        font-weight: 800;
      }

      .optional,
      .helper-text {
        color: var(--muted);
        font-size: 0.9375rem;
      }

      input {
        width: 100%;
        min-height: 3rem;
        border: 0.0625rem solid var(--field-border);
        border-radius: 0.75rem;
        padding: 0.75rem 1rem;
        color: var(--text);
        background: var(--field-bg);
        font: inherit;
      }

      input::placeholder {
        color: #8b949e;
        opacity: 1;
      }

      input:hover {
        border-color: var(--muted);
      }

      input:focus {
        border-color: var(--accent);
        outline: 0.1875rem solid transparent;
        box-shadow: 0 0 0 0.1875rem var(--accent);
      }

      button {
        min-height: 3.25rem;
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.5rem;
        color: var(--button-text);
        background: linear-gradient(135deg, var(--accent-strong), #8957e5);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.1);
      }

      button:focus {
        outline: 0.1875rem solid transparent;
        outline-offset: 0.25rem;
        box-shadow: 0 0 0 0.1875rem var(--text);
      }

      @media (max-width: 22rem) {
        main {
          padding-inline: 0.75rem;
        }

        .support-card {
          border-radius: 1rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .support-card,
        input {
          background: Canvas;
          color: CanvasText;
        }

        .support-card,
        input {
          border-color: ButtonBorder;
        }

        .eyebrow,
        .required,
        .optional,
        .helper-text {
          color: CanvasText;
        }

        button,
        .skip-link {
          border: 0.125rem solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div id="support-form-root"></div>
    </main>

    <script>
      const formFields = [
        {
          id: "full-name",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Johnson"
        },
        {
          id: "email-address",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@example.com"
        },
        {
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          helperText: "Optional. Use international format when possible, for example +1 555 123 4567."
        }
      ];

      function FormField(field) {
        const wrapper = document.createElement("div");
        wrapper.className = "form-field";

        const label = document.createElement("label");
        label.htmlFor = field.id;
        label.textContent = field.label;

        if (field.required) {
          const marker = document.createElement("span");
          marker.className = "required";
          marker.setAttribute("aria-hidden", "true");
          marker.textContent = " *";
          label.append(marker);
        } else {
          const optional = document.createElement("span");
          optional.className = "optional";
          optional.textContent = " (optional)";
          label.append(optional);
        }

        const input = document.createElement("input");
        input.id = field.id;
        input.name = field.id;
        input.type = field.type;
        input.autocomplete = field.autocomplete;
        input.placeholder = field.placeholder;

        if (field.required) {
          input.required = true;
          input.setAttribute("aria-required", "true");
        }

        wrapper.append(label, input);

        if (field.helperText) {
          const helper = document.createElement("p");
          helper.id = `${field.id}-helper`;
          helper.className = "helper-text";
          helper.textContent = field.helperText;
          input.setAttribute("aria-describedby", helper.id);
          wrapper.append(helper);
        }

        return wrapper;
      }

      function SupportContactForm() {
        const section = document.createElement("section");
        section.className = "support-card";
        section.setAttribute("aria-labelledby", "support-title");

        const eyebrow = document.createElement("p");
        eyebrow.className = "eyebrow";
        eyebrow.textContent = "Support";

        const heading = document.createElement("h1");
        heading.id = "support-title";
        heading.textContent = "Contact our team";

        const intro = document.createElement("p");
        intro.className = "intro";
        intro.textContent =
          "Tell us how to reach you and a support specialist will follow up with the next steps.";

        const form = document.createElement("form");
        form.noValidate = false;
        form.append(...formFields.map(FormField));

        const button = document.createElement("button");
        button.type = "submit";
        button.textContent = "Submit support request";
        form.append(button);

        form.addEventListener("submit", (event) => {
          const firstInvalidField = form.querySelector(":invalid");

          if (firstInvalidField) {
            event.preventDefault();
            firstInvalidField.focus();
          }
        });

        section.append(eyebrow, heading, intro, form);
        return section;
      }

      document
        .querySelector("#support-form-root")
        .append(SupportContactForm());
    </script>
  </body>
</html>
