<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --page-bg: #0d1117;
        --panel-bg: #151b23;
        --panel-border: #30363d;
        --text: #f0f6fc;
        --muted: #c9d1d9;
        --field-bg: #0d1117;
        --field-border: #8b949e;
        --accent: #58a6ff;
        --accent-strong: #2f81f7;
        --button-text: #ffffff;
        --shadow: #010409;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #1f6feb33, transparent 30rem),
          linear-gradient(135deg, #0d1117 0%, #161b22 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 1;
        transform: translateY(-160%);
        border-radius: 0.5rem;
        padding: 0.75rem 1rem;
        color: var(--button-text);
        background: var(--accent-strong);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 0.1875rem solid var(--text);
        outline-offset: 0.1875rem;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .support-card {
        width: min(100%, 42rem);
        border: 0.0625rem solid var(--panel-border);
        border-radius: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2.5rem);
        background: color-mix(in srgb, var(--panel-bg) 94%, transparent);
        box-shadow: 0 1.5rem 4rem var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent);
        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3.75rem);
        line-height: 1.05;
      }

      .intro {
        max-width: 36rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        color: var(--text);
        font-weight: 700;
      }

      .required {
        color: var(--accent);
        font-weight: 800;
      }

      .optional,
      .helper-text {
        color: var(--muted);
        font-size: 0.9375rem;
      }

      input {
        width: 100%;
        min-height: 3rem;
        border: 0.0625rem solid var(--field-border);
        border-radius: 0.75rem;
        padding: 0.75rem 1rem;
        color: var(--text);
        background: var(--field-bg);
        font: inherit;
      }

      input::placeholder {
        color: #8b949e;
        opacity: 1;
      }

      input:hover {
        border-color: var(--muted);
      }

      input:focus {
        border-color: var(--accent);
        outline: 0.1875rem solid transparent;
        box-shadow: 0 0 0 0.1875rem var(--accent);
      }

      button {
        min-height: 3.25rem;
        border: 0;
        border-radius: 999px;
        padding: 0.875rem 1.5rem;
        color: var(--button-text);
        background: linear-gradient(135deg, var(--accent-strong), #8957e5);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
      }

      button:hover {
        filter: brightness(1.1);
      }

      button:focus {
        outline: 0.1875rem solid transparent;
        outline-offset: 0.25rem;
        box-shadow: 0 0 0 0.1875rem var(--text);
      }

      @media (max-width: 22rem) {
        main {
          padding-inline: 0.75rem;
        }

        .support-card {
          border-radius: 1rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .support-card,
        input {
          background: Canvas;
          color: CanvasText;
        }

        .support-card,
        input {
          border-color: ButtonBorder;
        }

        .eyebrow,
        .required,
        .optional,
        .helper-text {
          color: CanvasText;
        }

        button,
        .skip-link {
          border: 0.125rem solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="support-card" aria-labelledby="support-title" data-component="SupportContactForm">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our team</h1>
        <p class="intro">
          Tell us how to reach you and a support specialist will follow up with
          the next steps.
        </p>

        <form>
          <div class="form-field" data-component="FormField">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              autocomplete="name"
              placeholder="Alex Johnson"
              required
              aria-required="true"
            >
          </div>

          <div class="form-field" data-component="FormField">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email-address"
              type="email"
              autocomplete="email"
              placeholder="alex@example.com"
              required
              aria-required="true"
            >
          </div>

          <div class="form-field" data-component="FormField">
            <label for="phone-number">Phone number <span class="optional">(optional)</span></label>
            <input
              id="phone-number"
              name="phone-number"
              type="tel"
              autocomplete="tel"
              placeholder="+1 555 123 4567"
              aria-describedby="phone-number-helper"
            >
            <p id="phone-number-helper" class="helper-text">
              Optional. Use international format when possible, for example +1
              555 123 4567.
            </p>
          </div>

          <button type="submit">Submit support request</button>
        </form>
      </section>
    </main>

    <script>
      function SupportContactForm(root) {
        const form = root.querySelector("form");

        form.addEventListener(
          "invalid",
          (event) => {
            event.target.focus();
          },
          true
        );
      }

      document
        .querySelectorAll('[data-component="SupportContactForm"]')
        .forEach(SupportContactForm);
    </script>
  </body>
</html>
