<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --page-bg: #0d1117;
        --panel-bg: #151b23;
        --panel-border: #30363d;
        --text: #f0f6fc;
        --muted: #c9d1d9;
        --field-bg: #0d1117;
        --field-border: #8b949e;
        --accent: #58a6ff;
        --accent-strong: #2f81f7;
        --button-text: #ffffff;
        --shadow: #010409;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
